document.getElementById("supplier-form").addEventListener("submit", async function(e) {
    e.preventDefault();

    const formData = Object.fromEntries(new FormData(this).entries());

    // Supplier data
    const supplier_data = {
        gstin: formData.gstin,
        supplier_name: formData.supplier_name,
        supplier_type: formData.supplier_type,
        gst_category: formData.gst_category,
        email_id: formData.email,
        phone: formData.phone
    };

    // Address data
    const address_data = {
        address_line1: formData.address_line1,
        address_line2: formData.address_line2,
        city: formData.city,
        state: formData.state,
        pincode: formData.pincode,
        country: formData.country
    };

    // Contact data
    const contact_data = {
        first_name: formData.supplier_name.split(" ")[0] || formData.supplier_name,
        last_name: formData.supplier_name.split(" ")[1] || "",
        email_id: formData.email,
        phone: formData.phone,
        is_primary_contact: 1
    };

    // Preferred billing/shipping
    if(formData.preferred_billing) {
        address_data.is_primary_address = 1;
        address_data.address_type = "Billing";
    } else if(formData.preferred_shipping) {
        address_data.is_primary_address = 1;
        address_data.address_type = "Shipping";
    }

    try {
        const r = await frappe.call({
            method: "yumaerp.api.register_supplier",
            args: {
                supplier_data: JSON.stringify(supplier_data),
                address_data: JSON.stringify(address_data),
                contact_data: JSON.stringify(contact_data)
            },
            freeze: true,
            freeze_message: "Registering Supplier..."
        });

        document.getElementById("msg").innerText = 
            `Supplier ${r.message.supplier} created with Address ${r.message.address} and Contact ${r.message.contact}`;

        this.reset();

    } catch(err) {
        document.getElementById("msg").innerText = "Error: " + (err.exc || err.message);
    }
});
